/* BUILT exercise library: every exercise the planner may prescribe, tagged
   by muscle group, movement pattern, equipment and the injuries it can
   aggravate, plus alternativesFor() for "Replace an exercise" (3 options for
   the same muscle group that fit the person's equipment and injuries).

   The library is exactly the owner's exercise sheet
   (supabase/functions/_shared/exercise-sheet.csv): one entry per sheet row,
   `sheetId` = the sheet's ID, `name` = its Exercise Name. The rows between
   the sheet-rows markers are generated by scripts/import-exercises.mjs;
   change the sheet or that script, never the rows by hand. Rows the sheet
   lists but no gym or home can be assumed to have room for (a pool, a
   track) carry `planner: false`: they stay findable, and are never
   prescribed or offered as a swap.

   Pure data and functions, no imports, so it runs anywhere.
   This file is byte-identical in two places:
     mobile/src/data/exercises.ts              (the app: instant swaps, offline)
     supabase/functions/_shared/exercises.ts   (the planner)
   mobile/src/__tests__/exercises.test.ts fails if they differ. */

export type Muscle =
  | 'chest' | 'back' | 'shoulders' | 'biceps' | 'triceps'
  | 'quads' | 'hamstrings' | 'glutes' | 'calves' | 'core'
  | 'full_body' | 'cardio';

export type Pattern =
  | 'push_horizontal' | 'push_vertical' | 'pull_horizontal' | 'pull_vertical'
  | 'squat' | 'hinge' | 'lunge' | 'carry' | 'core' | 'isolation' | 'conditioning' | 'mobility';

/** 'none' = bodyweight. 'machines' covers cables and every gym machine. */
export type Equipment = 'none' | 'dumbbells' | 'bands' | 'kettlebell' | 'pullup_bar' | 'bench' | 'machines' | 'barbell';

export type InjuryArea = 'knee' | 'lower_back' | 'shoulder' | 'wrist' | 'elbow' | 'hip' | 'ankle' | 'neck';

export type TrainLocation = 'home_none' | 'home_equipment' | 'gym';

export type Level = 'beginner' | 'intermediate' | 'advanced';

/** The sheet's Exercise Type. */
export type ExerciseKind = 'strength' | 'power' | 'conditioning' | 'mobility';

export type Exercise = {
  id: string;
  /** The row's ID in the exercise sheet. */
  sheetId: number;
  /** The sheet's Exercise Name, exactly. */
  name: string;
  /** Older or common names, so plans written by name still match. */
  aliases?: string[];
  muscle: Muscle;
  secondary: Muscle[];
  pattern: Pattern;
  kind: ExerciseKind;
  /** Everything it needs. ['none'] = bodyweight only. */
  equipment: Equipment[];
  /** Injury areas this exercise can aggravate; skipped for those people. */
  cautions: InjuryArea[];
  level: Level;
  unit: 'reps' | 's' | 'm';
  sets: number;
  /** reps, seconds or metres per set, by unit. Per side when the cue says so. */
  reps: number;
  /** rest between sets, seconds. */
  rest: number;
  /** One short form cue. */
  cue: string;
  /** false = needs a place no gym or home can be assumed to have (a pool, a
      track): never prescribed and never offered as a swap. */
  planner?: false;
};

export const ALL_EQUIPMENT: readonly Equipment[] = ['none', 'dumbbells', 'bands', 'kettlebell', 'pullup_bar', 'bench', 'machines', 'barbell'];
export const INJURY_AREAS: readonly InjuryArea[] = ['knee', 'lower_back', 'shoulder', 'wrist', 'elbow', 'hip', 'ankle', 'neck'];

type Opts = Partial<Pick<Exercise, 'aliases' | 'secondary' | 'unit' | 'sets' | 'reps' | 'rest' | 'cue' | 'planner'>>;

function x(
  sheetId: number,
  id: string,
  name: string,
  muscle: Muscle,
  pattern: Pattern,
  equipment: Equipment[],
  cautions: InjuryArea[],
  level: Level,
  kind: ExerciseKind,
  o: Opts = {},
): Exercise {
  const unit = o.unit ?? 'reps';
  return {
    id,
    sheetId,
    name,
    ...(o.aliases ? { aliases: o.aliases } : {}),
    muscle,
    secondary: o.secondary ?? [],
    pattern,
    kind,
    equipment,
    cautions,
    level,
    unit,
    sets: o.sets ?? 3,
    reps: o.reps ?? (unit === 's' ? 30 : unit === 'm' ? 250 : 10),
    rest: o.rest ?? (pattern === 'isolation' || pattern === 'core' ? 60 : 90),
    cue: o.cue ?? '',
    ...(o.planner === false ? { planner: false as const } : {}),
  };
}

